from pathlib import Path

SCRIPT = Path('scripts/apply_barmm_parliamentary_election_bb.py')
TEST = Path('tests/test_barmm_parliamentary_election_bb.py')

text = SCRIPT.read_text(encoding='utf-8')
old_import = 'from world_signals.live_intelligence import validate_live_intelligence\nfrom world_signals.validation import validate_registry\n'
new_import = 'from world_signals.live_intelligence import validate_live_intelligence\nfrom world_signals.checkpoint_contract import version_at_least\nfrom world_signals.validation import validate_registry\n'
if old_import not in text:
    raise SystemExit('BB import anchor missing')
